import { describe, expect, it } from 'vitest';
import { loadConfig } from '../src/config';
import { RateLimiter } from '../src/lib/limiter';
import { setup } from './helpers';

describe('POST /webhooks rate limiting', () => {
  it('answers 429 with a Retry-After header when a tenant exceeds the limit', async () => {
    const { postWebhook } = setup({ rateLimitMax: 2, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(202);

    const res = await postWebhook('tenant-a', { type: 'c' });
    expect(res.status).toBe(429);
    const retryAfter = res.headers.get('Retry-After');
    expect(retryAfter).toMatch(/^\d+$/);
    expect(Number(retryAfter)).toBeGreaterThan(0);
    expect(await res.json()).toMatchObject({ error: 'rate limit exceeded' });
  });

  it('does not affect other tenants', async () => {
    const { postWebhook } = setup({ rateLimitMax: 1, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(429);
    expect((await postWebhook('tenant-b', { type: 'c' })).status).toBe(202);
  });

  it('honours the limit from config rather than a fixed constant', async () => {
    const { postWebhook } = setup({ rateLimitMax: 3, rateLimitWindowMs: 60000 });
    for (let i = 0; i < 3; i++) {
      expect((await postWebhook('tenant-a', { type: `t${i}` })).status).toBe(202);
    }
    expect((await postWebhook('tenant-a', { type: 'over' })).status).toBe(429);
  });

  it('does not record an audit entry for a rejected webhook', async () => {
    const { postWebhook, deps } = setup({ rateLimitMax: 1, rateLimitWindowMs: 60000 });
    await postWebhook('tenant-a', { type: 'a' });
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(429);
    expect(deps.audit.list()).toHaveLength(1);
  });
});

describe('RateLimiter', () => {
  it('allows up to the limit within the window per key', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('t', 2, 1000, 0).allowed).toBe(true);
    expect(limiter.check('t', 2, 1000, 100).allowed).toBe(true);
    const verdict = limiter.check('t', 2, 1000, 200);
    expect(verdict.allowed).toBe(false);
    expect(verdict.retryAfterSec).toBeGreaterThan(0);
  });

  it('tracks keys independently', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('a', 1, 1000, 0).allowed).toBe(true);
    expect(limiter.check('a', 1, 1000, 100).allowed).toBe(false);
    expect(limiter.check('b', 1, 1000, 100).allowed).toBe(true);
  });

  it('resets the count once the window elapses', () => {
    const limiter = new RateLimiter();
    expect(limiter.check('t', 1, 1000, 0).allowed).toBe(true);
    expect(limiter.check('t', 1, 1000, 500).allowed).toBe(false);
    expect(limiter.check('t', 1, 1000, 1000).allowed).toBe(true);
  });
});

describe('rate limit config', () => {
  it('defaults the limit and window', () => {
    expect(loadConfig({})).toMatchObject({ rateLimitMax: 100, rateLimitWindowMs: 60000 });
  });

  it('reads the limit and window from the environment', () => {
    expect(loadConfig({ RATE_LIMIT_MAX: '5', RATE_LIMIT_WINDOW_MS: '1000' })).toMatchObject({
      rateLimitMax: 5,
      rateLimitWindowMs: 1000,
    });
  });
});

